package org.updraft.betterstatus.backend;
import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.plugin.messaging.PluginMessageListener;import org.updraft.betterstatus.protocol.StatusProtocol;import org.updraft.betterstatus.protocol.StatusProtocol.WireStatus;import org.updraft.betterstatus.model.ServerState;import java.io.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
public final class BackendStatusPlugin extends JavaPlugin implements PluginMessageListener {private static final String CHANNEL="BungeeCord";private final Map<String,WireStatus> cache=new ConcurrentHashMap<>();
 @Override public void onEnable(){getServer().getMessenger().registerOutgoingPluginChannel(this,CHANNEL);getServer().getMessenger().registerIncomingPluginChannel(this,CHANNEL,this);if(getServer().getPluginManager().getPlugin("PlaceholderAPI")!=null){new StatusExpansion(this).register();getLogger().info("PlaceholderAPI expansion registered.");}else getLogger().warning("PlaceholderAPI not found; placeholders disabled.");getServer().getScheduler().runTaskTimer(this,this::requestStatus,40L,100L);}
 private void requestStatus(){Player p=getServer().getOnlinePlayers().stream().findFirst().orElse(null);if(p==null)return;try{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);out.writeUTF(StatusProtocol.SUBCHANNEL);p.sendPluginMessage(this,CHANNEL,b.toByteArray());}catch(IOException ignored){}}
 @Override public void onPluginMessageReceived(String channel,Player player,byte[] data){if(!CHANNEL.equals(channel))return;try{for(WireStatus s:StatusProtocol.decode(data))cache.put(s.name().toLowerCase(Locale.ROOT),s);}catch(IOException ex){getLogger().warning("Ignored malformed status packet.");}}
 public String resolve(String params){if(params==null||params.isBlank())return "";String key=params.toLowerCase(Locale.ROOT),field="status";int i=key.lastIndexOf('_');if(i>0&&Set.of("state","players","max","ping","motd","version","uptime","downtime","lastseen","online","health").contains(key.substring(i+1))){field=key.substring(i+1);key=key.substring(0,i);}WireStatus s=cache.get(key);if(s==null)return "Unknown";return switch(field){case "state","health"->s.state().name();case "players"->Integer.toString(s.players());case "max"->Integer.toString(s.maxPlayers());case "ping"->s.pingMillis()<0?"Unknown":Long.toString(s.pingMillis());case "motd"->s.motd();case "version"->s.version();case "uptime"->Long.toString(s.uptimeSeconds());case "downtime"->Long.toString(s.downtimeSeconds());case "lastseen"->s.lastSuccessMillis()<=0?"Never":Long.toString(s.lastSuccessMillis());case "online"->Boolean.toString(s.state()==ServerState.ONLINE||s.state()==ServerState.DEGRADED);default->s.legacyStatus();};}
 @Override public void onDisable(){getServer().getMessenger().unregisterOutgoingPluginChannel(this,CHANNEL);getServer().getMessenger().unregisterIncomingPluginChannel(this,CHANNEL);}}
